// neural_core.h — the model-only hexapod controller, portable C (no Arduino).
//
// The network (policy_weights.h, generated by tools/export_policy_weights.py)
// is a 21 -> 256 -> 128 -> 64 -> 36 MLP with swish activations. Its inputs are
//   [0..3]  IMU quaternion  (constant 1,0,0,0 — no IMU fitted)
//   [4..6]  IMU gyro        (constant 0)
//   [7..9]  IMU accel       (constant 0)
//   [10,11] gait clock      sin(2*pi*phase), cos(2*pi*phase), phase = (t / period) mod 1
//   [12..20] command        vx vy wz pitch roll height_delta width_delta shift_x shift_y
// and its first 18 outputs become joint targets: neutral + tanh(out) * residual_scale,
// radians, simulator convention + simulator leg order (RR RM RF LR LM LF x coxa femur tibia).
//
// nc_stance() is the standing pose for the moments the network has no business
// running (it never saw a zero-velocity command): the scaffold's own rest pose
// at a given height/width delta, reproduced bit-for-bit (checked by the exporter).
//
// The same file is compiled on the host by tools/check_neural_core.py against the
// Python reference, and by the firmware — keep it free of Arduino calls.
#pragma once
#include <math.h>
#include "policy_weights.h"

#define NC_PI 3.14159265358979323846f

static inline float nc_swish(float x) { return x / (1.0f + expf(-x)); }

// W is row-major [in][out]. Stream it row by row: the weights sit in flash behind a small
// cache on the ESP32-S3, and a column-wise walk (one element per cache line) made a single
// evaluation take ~46 ms; sequential rows take ~2 ms.
static void nc_dense(const float* in, int n_in, const float* W, const float* b, float* out, int n_out, int act) {
  for (int o = 0; o < n_out; ++o) out[o] = b[o];
  for (int i = 0; i < n_in; ++i) {
    const float x = in[i];
    if (x == 0.0f) continue;
    const float* w = W + (size_t)i * n_out;
    for (int o = 0; o < n_out; ++o) out[o] += x * w[o];
  }
  if (act) for (int o = 0; o < n_out; ++o) out[o] = nc_swish(out[o]);
}

// obs[21] -> joints[18] (radians, sim convention/order).
static void nc_policy(const float* obs, float* joints) {
  static float x0[POLICY_OBS_DIM], h0[256], h1[128], h2[64], out[36];
  for (int i = 0; i < POLICY_OBS_DIM; ++i) x0[i] = (obs[i] - POLICY_OBS_MEAN[i]) / POLICY_OBS_STD[i];
  nc_dense(x0, POLICY_OBS_DIM, POLICY_W0, POLICY_B0, h0, 256, 1);
  nc_dense(h0, 256, POLICY_W1, POLICY_B1, h1, 128, 1);
  nc_dense(h1, 128, POLICY_W2, POLICY_B2, h2, 64, 1);
  nc_dense(h2, 64, POLICY_W3, POLICY_B3, out, 36, 0);
  for (int j = 0; j < POLICY_ACT_DIM; ++j) joints[j] = POLICY_NEUTRAL_POSE[j] + tanhf(out[j]) * POLICY_RESIDUAL_SCALE;
}

// phase in [0,1), cmd[9] -> obs[21]. Pitch, roll and the body shifts must be 0:
// they were constant in training and their normaliser std is 1e-6.
static void nc_build_obs(float phase, const float* cmd, float* obs) {
  obs[0] = 1.0f; obs[1] = obs[2] = obs[3] = 0.0f;
  for (int i = 4; i < 10; ++i) obs[i] = 0.0f;
  obs[10] = sinf(2.0f * NC_PI * phase);
  obs[11] = cosf(2.0f * NC_PI * phase);
  for (int i = 0; i < 9; ++i) obs[12 + i] = cmd[i];
}

static inline float nc_clampf(float v, float lo, float hi) { return v < lo ? lo : (v > hi ? hi : v); }

// Height delta (+ = body lower) and width delta allowed by the stance envelope.
static inline float nc_clamp_dh(float dh) { return nc_clampf(dh, POLICY_DH_MIN, POLICY_DH_MAX); }
static inline float nc_clamp_dw(float dh, float dw) {
  float lo = POLICY_DW_MIN_INTERCEPT + POLICY_DW_MIN_SLOPE * dh;
  float hi = POLICY_DW_MAX_INTERCEPT + POLICY_DW_MAX_SLOPE * dh;
  return nc_clampf(dw, lo, hi);
}

// Closed-form 3-link IK, geometric convention (gait/controller.py:_ik_raw).
static void nc_ik_raw(float fx, float fy, float fz, float* coxa, float* femur, float* tibia) {
  const float L1 = POLICY_L1, L2 = POLICY_L2, L3 = POLICY_L3;
  *coxa = atan2f(fy, fx);
  float r = hypotf(fx, fy);
  float x_fp = r - L1, z_fp = fz;
  float D = hypotf(x_fp, z_fp);
  if (D > L2 + L3 - 1e-6f) D = L2 + L3 - 1e-6f;
  if (D < fabsf(L2 - L3) + 1e-6f) D = fabsf(L2 - L3) + 1e-6f;
  float cos_a = nc_clampf((L2 * L2 + D * D - L3 * L3) / (2.0f * L2 * D), -1.0f, 1.0f);
  float cos_g = nc_clampf((L2 * L2 + L3 * L3 - D * D) / (2.0f * L2 * L3), -1.0f, 1.0f);
  float alpha = acosf(cos_a), gamma = acosf(cos_g), beta = atan2f(z_fp, x_fp);
  *femur = beta + alpha;
  *tibia = NC_PI - gamma;
}

#ifndef POLICY_PITCH_MAX
#define POLICY_PITCH_MAX 0.0f
#define POLICY_ROLL_MAX 0.0f
#endif

// Standing pose at (dh, dw, pitch, roll) -> joints[18] (sim convention/order).
// Tilt = gait/controller.py:_apply_tilt: coxa-local -> body, rotate by
// R^-1 with R = R_y(-pitch)·R_x(roll) (pitch+ nose up, roll+ left side up), -> coxa-local.
static void nc_stance_tilt(float dh, float dw, float pitch, float roll, float joints[18]) {
  float cp = cosf(pitch), sp = sinf(pitch), cr = cosf(roll), sr = sinf(roll);
  for (int leg = 0; leg < 6; ++leg) {
    float fx = POLICY_FOOT_REST_COXA[leg * 3 + 0] + dw;
    float fy = POLICY_FOOT_REST_COXA[leg * 3 + 1];
    float fz = POLICY_FOOT_REST_COXA[leg * 3 + 2] + dh;
    if (pitch != 0.0f || roll != 0.0f) {
      float c = POLICY_LEG_YAW_C[leg], s = POLICY_LEG_YAW_S[leg];
      float bx = c * fx - s * fy + POLICY_COXA_POS_BODY[leg * 3 + 0];          // coxa-local -> body
      float by = s * fx + c * fy + POLICY_COXA_POS_BODY[leg * 3 + 1];
      float bz = fz + POLICY_COXA_POS_BODY[leg * 3 + 2];
      float tx = cp * bx + sp * bz;                                             // R^-1 rows
      float ty = -sp * sr * bx + cr * by + cp * sr * bz;
      float tz = -sp * cr * bx - sr * by + cp * cr * bz;
      float rx = tx - POLICY_COXA_POS_BODY[leg * 3 + 0];                        // body -> coxa-local
      float ry = ty - POLICY_COXA_POS_BODY[leg * 3 + 1];
      fx = c * rx + s * ry; fy = -s * rx + c * ry; fz = tz - POLICY_COXA_POS_BODY[leg * 3 + 2];
    }
    float raw[3];
    nc_ik_raw(fx, fy, fz, &raw[0], &raw[1], &raw[2]);
    for (int j = 0; j < 3; ++j)
      joints[leg * 3 + j] = POLICY_JOINT_SIGNS[leg * 3 + j] * raw[j] + POLICY_LEG_OFFSETS[leg * 3 + j];
  }
}
static void nc_stance(float dh, float dw, float joints[18]) { nc_stance_tilt(dh, dw, 0.0f, 0.0f, joints); }
